<?php $byDay=[]; foreach($items as $item)$byDay[(int)$item['weekday']]=$item; $names=array_map('t',[1=>'Понедельник',2=>'Вторник',3=>'Среда',4=>'Четверг',5=>'Пятница',6=>'Суббота',7=>'Воскресенье']); $types=array_map('t',['strength'=>'Зал','swimming'=>'Бассейн','cardio'=>'Кардио','mobility'=>'Мобильность','other'=>'Другое']); ?>
<section class="page-head"><div><p class="eyebrow">Повторяющаяся неделя</p><h1>Расписание</h1><p class="muted">По умолчанию: понедельник и среда — зал, четверг — бассейн.</p></div></section>
<?php if($error): ?><div class="alert alert-error"><?= te($error) ?></div><?php endif; ?><?php if($success): ?><div class="alert alert-success"><?= te($success) ?></div><?php endif; ?>
<form method="post" action="<?= e(url('/schedule')) ?>" class="stack-form"><input type="hidden" name="_csrf" value="<?= e(\App\Core\Csrf::token()) ?>"><div class="schedule-grid"><?php foreach($names as $day=>$name): $row=$byDay[$day]??null; ?><article class="card schedule-day"><label class="check-row"><input type="checkbox" name="days[<?= $day ?>][active]" value="1" <?= $row && (int)$row['active']===1?'checked':'' ?>><strong><?= e($name) ?></strong></label><label>Тип<select name="days[<?= $day ?>][workout_type]"><?php foreach($types as $value=>$label): ?><option value="<?= e($value) ?>" <?= ($row['workout_type']??'strength')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Название<input name="days[<?= $day ?>][label]" maxlength="120" value="<?= e($row['label']??'Тренировка') ?>"></label></article><?php endforeach; ?></div><button class="button button-primary">Сохранить неделю</button><a class="button button-quiet" href="<?= e(url('/swimming')) ?>">К плаванию</a></form>
